:root {
  --bg: #1e1b2e;
  --card: #2d2a45;
  --accent: #ffb347;
  --accent-dark: #cc8a2e;
  --text: #f5f0ff;
  --muted: #a99fc4;
  --pip: #1e1b2e;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  background-image: linear-gradient(135deg, #1e1b2e 25%, #241f38 25%, #241f38 50%, #1e1b2e 50%, #1e1b2e 75%, #241f38 75%);
  background-size: 32px 32px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 3px solid var(--accent);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 8px 0 rgba(0,0,0,0.35);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

h2 {
  margin: 0 0 8px;
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

fieldset {
  border: none;
  margin: 0;
  padding: 0;
}

legend {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 8px;
}

.dice-options {
  display: flex;
  gap: 10px;
}

.dice-option {
  flex: 1;
  position: relative;
}

.dice-option input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  cursor: pointer;
}

.dice-option span {
  display: block;
  padding: 12px 0;
  text-align: center;
  font-size: 1.1rem;
  font-weight: 700;
  background: #3b3660;
  border: 2px solid #4d477a;
  border-radius: 8px;
  color: var(--text);
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.dice-option input:hover + span {
  background: #4a4475;
  border-color: var(--accent);
}

.dice-option input:focus-visible + span {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.dice-option input:checked + span {
  background: var(--accent);
  border-color: var(--accent-dark);
  color: var(--bg);
}

.dice-option input:active + span {
  transform: translateY(2px);
}

.roll-btn {
  font: inherit;
  font-weight: 700;
  font-size: 1.1rem;
  padding: 14px;
  border: 3px solid var(--accent-dark);
  border-radius: 8px;
  background: var(--accent);
  color: var(--bg);
  cursor: pointer;
  transition: background 0.15s, transform 0.05s, box-shadow 0.05s;
  box-shadow: 0 4px 0 var(--accent-dark);
}

.roll-btn:hover { background: #ffc470; }
.roll-btn:focus-visible { outline: 3px solid var(--text); outline-offset: 3px; }
.roll-btn:active { transform: translateY(3px); box-shadow: 0 1px 0 var(--accent-dark); }

.dice-area { text-align: center; }

.dice-display {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  min-height: 64px;
  align-items: center;
}

.die {
  width: 64px;
  height: 64px;
  background: #f5f0ff;
  border: 3px solid var(--accent);
  border-radius: 10px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  padding: 8px;
  gap: 2px;
  box-shadow: inset 0 0 0 2px #d8cff0;
  animation: pop 0.2s ease-out;
}

@keyframes pop {
  from { transform: scale(0.6); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.pip {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: transparent;
}

.pip.on { background: var(--pip); }

.total {
  margin: 12px 0 0;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
  min-height: 1.5em;
}

.history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 0.95rem;
}

.history-list li {
  background: #3b3660;
  border-left: 4px solid var(--accent);
  border-radius: 6px;
  padding: 8px 12px;
  color: var(--text);
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.history-list .empty {
  border-left-color: var(--muted);
  color: var(--muted);
  font-style: italic;
  justify-content: center;
}

@media (max-width: 380px) {
  body { padding: 10px; }
  .card { padding: 18px; gap: 16px; }
  .die { width: 54px; height: 54px; padding: 6px; }
  h1 { font-size: 1.25rem; }
}

(function () {
  'use strict';

  var diceDisplay = document.getElementById('dice-display');
  var totalEl = document.getElementById('total');
  var historyList = document.getElementById('history-list');
  var rollBtn = document.getElementById('roll-btn');
  var countInputs = document.querySelectorAll('input[name="dice-count"]');

  var history = [];
  var MAX_HISTORY = 5;

  // Pip positions per face value (1-6) on a 3x3 grid (indices 0-8)
  var FACES = {
    1: [4],
    2: [0, 8],
    3: [0, 4, 8],
    4: [0, 2, 6, 8],
    5: [0, 2, 4, 6, 8],
    6: [0, 2, 3, 5, 6, 8]
  };

  function getDiceCount() {
    for (var i = 0; i < countInputs.length; i++) {
      if (countInputs[i].checked) return parseInt(countInputs[i].value, 10);
    }
    return 1;
  }

  function createDie(value) {
    var die = document.createElement('div');
    die.className = 'die';
    die.setAttribute('role', 'img');
    die.setAttribute('aria-label', 'Die showing ' + value);

    var active = FACES[value] || [];
    for (var i = 0; i < 9; i++) {
      var pip = document.createElement('span');
      pip.className = active.indexOf(i) !== -1 ? 'pip on' : 'pip';
      die.appendChild(pip);
    }
    return die;
  }

  function renderDice(values) {
    diceDisplay.innerHTML = '';
    values.forEach(function (v) {
      diceDisplay.appendChild(createDie(v));
    });
  }

  function renderHistory() {
    historyList.innerHTML = '';
    if (history.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty';
      empty.textContent = 'No rolls yet';
      historyList.appendChild(empty);
      return;
    }
    history.forEach(function (entry) {
      var li = document.createElement('li');
      var diceSpan = document.createElement('span');
      diceSpan.textContent = entry.values.join(' + ') + ' = ' + entry.total;
      li.appendChild(diceSpan);
      historyList.appendChild(li);
    });
  }

  function roll() {
    var count = getDiceCount();
    var values = [];
    var total = 0;
    for (var i = 0; i < count; i++) {
      var v = Math.floor(Math.random() * 6) + 1;
      values.push(v);
      total += v;
    }

    renderDice(values);
    totalEl.textContent = 'Total: ' + total;

    history.unshift({ values: values, total: total });
    if (history.length > MAX_HISTORY) history.pop();
    renderHistory();
  }

  rollBtn.addEventListener('click', roll);

  renderHistory();
})();
